package org.kylepitcock.legacyconnector.loader.synth;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import org.kylepitcock.legacyconnector.loader.LegacyVersion;

/**
 * Supertypes and access flags of every class of a legacy Minecraft + Forge version, under their original
 * (unrelocated) names. Generated by {@code tools/extract_legacy_hierarchy.py}; names and supertypes only.
 *
 * <p>Synthesized API classes must sit at the right place in the hierarchy: a synthesized {@code BlockColored}
 * has to <em>be</em> a shim {@code Block} for {@code GameRegistry.registerBlock} to accept it.</p>
 */
public final class LegacyHierarchyData {
    public record Entry(String name, String superName, List<String> interfaces, int access) {}

    private static final Map<LegacyVersion, LegacyHierarchyData> CACHE = new ConcurrentHashMap<>();

    private final Map<String, Entry> entries;

    private LegacyHierarchyData(Map<String, Entry> entries) {
        this.entries = entries;
    }

    public static LegacyHierarchyData forVersion(LegacyVersion version) {
        return CACHE.computeIfAbsent(version, LegacyHierarchyData::load);
    }

    /** Null for classes that did not exist in that version (or that the data does not know). */
    public Entry get(String legacyName) {
        return entries.get(legacyName);
    }

    /** Named member classes declared directly in {@code legacyName} (not anonymous/local ones). */
    public List<String> nested(String legacyName) {
        String prefix = legacyName + "$";
        List<String> out = new java.util.ArrayList<>();
        for (String n : entries.keySet()) {
            if (!n.startsWith(prefix)) continue;
            String rest = n.substring(prefix.length());
            if (!rest.isEmpty() && rest.indexOf('$') < 0 && !Character.isDigit(rest.charAt(0))) out.add(n);
        }
        return out;
    }

    private static LegacyHierarchyData load(LegacyVersion version) {
        Map<String, Entry> map = new HashMap<>();
        String resource = "legacyconnector/legacy/" + version.id() + "/hierarchy.txt";
        try (InputStream in = LegacyHierarchyData.class.getClassLoader().getResourceAsStream(resource)) {
            if (in != null) {
                BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
                String line;
                while ((line = r.readLine()) != null) {
                    String[] p = line.split(" ");
                    if (p.length < 4) continue;
                    List<String> ifaces = p[2].equals("-") ? List.of() : Arrays.asList(p[2].split(","));
                    map.put(p[0], new Entry(p[0], p[1].equals("-") ? null : p[1], ifaces, Integer.parseInt(p[3])));
                }
            }
        } catch (IOException e) {
            throw new IllegalStateException("Cannot read " + resource, e);
        }
        return new LegacyHierarchyData(map);
    }
}
